  // step loop (Custom): init RunState.LoopIndex = 0; while RunState.LoopIndex < GetNumElements(Parameters.Sequence.Setup); increment RunState.LoopIndex += 1; status "Passed"
  final loop = ts.StepLoop();
  loop.index = 0; // loop initialize
  while (loop.index < ts.getNumElements(sequence.Setup)) {
    // loop while
    forEachSetupStepResult = ts.PropObj({
      'Error': ts.PropObj({'Code': 0, 'Msg': '', 'Occurred': false}),
      'Status': '',
      'ReportText': '',
      'Common': ts.PropObj(),
    });
    final docResultRef3 = ts.Ref<String>(docResultRef.value);
    final stepsSoFarRef = ts.Ref<int>(stepsSoFar);
    final previousBlockLevelRef = ts.Ref<int>(previousBlockLevel);
    forEachSetupStepResult.Status = await stepDoc(
      step: sequence.Setup[loop.index.toInt()],
      docResult: docResultRef3,
      totalNumSteps: totalNumSteps,
      stepsSoFar: stepsSoFarRef,
      previousBlockLevel: previousBlockLevelRef,
    ); // For Each Setup Step
    docResultRef.value = docResultRef3.value;
    stepsSoFar = stepsSoFarRef.value;
    previousBlockLevel = previousBlockLevelRef.value;
    forEachSetupStepResult.Status = forEachSetupStepResult.Status == 'Done'
        ? 'Passed'
        : forEachSetupStepResult.Status; // status expression
    loop.count(forEachSetupStepResult.Status);
    loop.index += 1; // loop increment
  }
  forEachSetupStepResult.Status = 'Passed'; // loop status
  run.record(forEachSetupStepResult.Status);
  if (ts.getNumElements(sequence.Main) > 0) {
    // precondition of Main Steps Header
    docResultRef.value +=
        '<H3>${ts.stepHost.resourceString('EXECUTION PHASE', 'MainSteps')}</H3>\n'; // Main Steps Header
  }
  previousBlockLevel = 0; // Reset Previous Block Level_Copy
  // status expression: (Step.Result.Status == "Done" && (Step.TS.SData.ThreadOpt == 0 || Step.TS.SData.ThreadOpt == 3)) ? "Passed" : Step.Result.Status
  // step loop (Custom): init RunState.LoopIndex = 0; while RunState.LoopIndex < GetNumElements(Parameters.Sequence.Main); increment RunState.LoopIndex += 1; status "Passed"
  final loop2 = ts.StepLoop();
  loop2.index = 0; // loop initialize
  while (loop2.index < ts.getNumElements(sequence.Main)) {
    // loop while
    forEachMainStepResult = ts.PropObj({
      'Error': ts.PropObj({'Code': 0, 'Msg': '', 'Occurred': false}),
      'Status': '',
      'ReportText': '',
      'Common': ts.PropObj(),
    });
    final docResultRef4 = ts.Ref<String>(docResultRef.value);
    final stepsSoFarRef2 = ts.Ref<int>(stepsSoFar);
    final previousBlockLevelRef2 = ts.Ref<int>(previousBlockLevel);
    forEachMainStepResult.Status = await stepDoc(
      step: sequence.Main[loop2.index.toInt()],
      docResult: docResultRef4,
      totalNumSteps: totalNumSteps,
      stepsSoFar: stepsSoFarRef2,
      previousBlockLevel: previousBlockLevelRef2,
    ); // For Each Main Step
    docResultRef.value = docResultRef4.value;
    stepsSoFar = stepsSoFarRef2.value;
    previousBlockLevel = previousBlockLevelRef2.value;
    forEachMainStepResult.Status = forEachMainStepResult.Status == 'Done'
        ? 'Passed'
        : forEachMainStepResult.Status; // status expression
    loop2.count(forEachMainStepResult.Status);
    loop2.index += 1; // loop increment
  }
  forEachMainStepResult.Status = 'Passed'; // loop status
  run.record(forEachMainStepResult.Status);
  if (ts.getNumElements(sequence.Cleanup) > 0) {
    // precondition of Cleanup Steps Header
    docResultRef.value +=
        '<H3>${ts.stepHost.resourceString('EXECUTION PHASE', 'Cleanup')}</H3>\n'; // Cleanup Steps Header
  }
  previousBlockLevel = 0; // Reset Previous Block Level_Copy2
  // status expression: (Step.Result.Status == "Done" && (Step.TS.SData.ThreadOpt == 0 || Step.TS.SData.ThreadOpt == 3)) ? "Passed" : Step.Result.Status
  // step loop (Custom): init RunState.LoopIndex = 0; while RunState.LoopIndex < GetNumElements(Parameters.Sequence.Cleanup); increment RunState.LoopIndex += 1; status "Passed"
  final loop3 = ts.StepLoop();
  loop3.index = 0; // loop initialize
  while (loop3.index < ts.getNumElements(sequence.Cleanup)) {
    // loop while
    forEachCleanupStepResult = ts.PropObj({
      'Error': ts.PropObj({'Code': 0, 'Msg': '', 'Occurred': false}),
      'Status': '',
      'ReportText': '',
      'Common': ts.PropObj(),
    });
    final docResultRef5 = ts.Ref<String>(docResultRef.value);
    final stepsSoFarRef3 = ts.Ref<int>(stepsSoFar);
    final previousBlockLevelRef3 = ts.Ref<int>(previousBlockLevel);
    forEachCleanupStepResult.Status = await stepDoc(
      step: sequence.Cleanup[loop3.index.toInt()],
      docResult: docResultRef5,
      totalNumSteps: totalNumSteps,
      stepsSoFar: stepsSoFarRef3,
      previousBlockLevel: previousBlockLevelRef3,
    ); // For Each Cleanup Step
    docResultRef.value = docResultRef5.value;
    stepsSoFar = stepsSoFarRef3.value;
    previousBlockLevel = previousBlockLevelRef3.value;
    forEachCleanupStepResult.Status = forEachCleanupStepResult.Status == 'Done'
        ? 'Passed'
        : forEachCleanupStepResult.Status; // status expression
    loop3.count(forEachCleanupStepResult.Status);
    loop3.index += 1; // loop increment
  }
  forEachCleanupStepResult.Status = 'Passed'; // loop status
  run.record(forEachCleanupStepResult.Status);

  return run.status;
}

/// Sequence `Step Doc`.
Future<String> stepDoc({
  dynamic step,
  ts.Ref<String>? docResult,
  double totalNumSteps = 0,
  ts.Ref<int>? stepsSoFar,
  ts.Ref<int>? previousBlockLevel,
}) async {
  final docResultRef = docResult ?? ts.Ref<String>('');
  final stepsSoFarRef = stepsSoFar ?? ts.Ref<int>(0);
  final previousBlockLevelRef = previousBlockLevel ?? ts.Ref<int>(0);
  const String rowHtml = '<TR>'; // Str
  const String propColHtml = '<TD WIDTH=30% NOWRAP=NOWRAP BGCOLOR=LIGHTBLUE>'; // Str
  const String valColHtml = '<TD WIDTH=70% BGCOLOR=LIGHTGREEN>'; // Str
  String tmpString = ''; // Str
  const String execFlow = ''; // Str
  const String stepKeyName = ''; // Str
  const int blockLevel = 0; // Num — default: 0

  final run = ts.SequenceRun();
  final dynamic getStepTypeNameResult = ts.PropObj({
    'Error': ts.PropObj({'Code': 0, 'Msg': '', 'Occurred': false}),
    'Status': '',
    'PassFail': true,
    'ReportText': '',
    'Common': ts.PropObj(),
  }); // result of Get StepType Name
  final dynamic addRequirementsResult = ts.PropObj({
    'Error': ts.PropObj({'Code': 0, 'Msg': '', 'Occurred': false}),
    'Status': '',
    'ReportText': '',
    'Common': ts.PropObj(),
  }); // result of Add Requirements
  final dynamic addMultipleNumericLimitsResult = ts.PropObj({
    'Error': ts.PropObj({'Code': 0, 'Msg': '', 'Occurred': false}),
    'Status': '',
    'ReportText': '',
    'Common': ts.PropObj(),
  }); // result of Add Multiple Numeric Limits

  skipToBeginOfMultipleLimits:
  {
    //   Return Value -> Locals.BlockLevel
    ts.notExported('cModule call: Get Block Level'); // Get Block Level [Action]
    if (blockLevel > previousBlockLevelRef.value) {
      // precondition of Indent For Block
      docResultRef.value += '<BLOCKQUOTE>'; // Indent For Block
    }
    if (blockLevel < previousBlockLevelRef.value) {
      // precondition of Unindent For Block
      docResultRef.value += '</BLOCKQUOTE>'; // Unindent For Block
    }
    previousBlockLevelRef.value = blockLevel; // Remember Last Block Level
    stepsSoFarRef.value += 1; // Update StepsSoFar
    ts.notExported('cModule call: Update Percent Done'); // Update Percent Done [Action]
    ts.eval(
      'Parameters.DocResult += "<BLOCKQUOTE>" + Locals.TableHTML + Locals.RowHTML + Locals.TitleColHTML +\n	"<FONT COLOR=WHITE SIZE=+2><B>" +\n	GetResourceString("SEQ_FILE_DOC", "DOC_STEP_NAME") +\n	NameOf(Parameters.Step) + "</B></FONT>\\n"\n',
    ); // Step Header
    // checks: Step.Result.PassFail
    // status expression: Step.Result.PassFail ? "Passed" : "Failed"
    ts.notExported('cModule call: Get StepType Name'); // Get StepType Name [PassFailTest]
    getStepTypeNameResult.Status = ts.truthy(getStepTypeNameResult.PassFail) ? 'Passed' : 'Failed'; // status expression
    run.record(getStepTypeNameResult.Status);
    //   Return Value -> Locals.StepKeyName
    ts.notExported('cModule call: GetStepKeyName'); // GetStepKeyName [Action]
    tmpString = ts.stepHost.resourceString('Adapter Names', stepKeyName); // Process Adapter Name
    ts.eval('\nFindAndReplace(Locals.tmpString, "<", "&lt;")'); // Process Adapter Name (cont.)
    ts.eval('\nFindAndReplace(Locals.tmpString, ">", "&gt;")'); // Process Adapter Name (cont.)
    ts.eval('\nFindAndReplace(Locals.tmpString, "\\n", "<BR>")'); // Process Adapter Name (cont.)
    ts.eval(
      'Parameters.DocResult += Locals.RowHTML+ Locals.PropColHTML +\nStr(ResStr("SEQ_FILE_DOC", "DOC_STEP_TYPE_AND_ADAPTER"), "%-30s") +\nLocals.ValColHTML +\nResStr("STEPTYPE_NAMES", Locals.StepTypeName, Locals.StepTypeName) + \n", " + Locals.tmpString + "\\n"\n',
    ); // Step Type, Adapter Name
    //   Return Value -> Locals.tmpString
    //   options <- 1 ' long description
    ts.notExported('cModule call: Get Step Desc'); // Get Step Desc [Action]
    ts.eval('FindAndReplace(Locals.tmpString, "<", "&lt;")'); // Process Desc
    ts.eval('\nFindAndReplace(Locals.tmpString, ">", "&gt;")'); // Process Desc (cont.)
    ts.eval('\nFindAndReplace(Locals.tmpString, "\\n", "<BR>")'); // Process Desc (cont.)
    docResultRef.value +=
        '${rowHtml + propColHtml + ts.stepHost.resourceString('SEQ_FILE_DOC', 'DOC_STEP_DESC') + valColHtml + tmpString}\n'; // Step Description
    ts.eval('Locals.tmpString = CommentOf(Parameters.Step)'); // Process Comment
    ts.eval('\nFindAndReplace(Locals.tmpString, "<", "&lt;")'); // Process Comment (cont.)
    ts.eval('\nFindAndReplace(Locals.tmpString, ">", "&gt;")'); // Process Comment (cont.)
    ts.eval('\nFindAndReplace(Locals.tmpString, "\\n", "<BR>")'); // Process Comment (cont.)
    if (ts.cond('CommentOf(Parameters.Step) != ""')) {
      // precondition of Comment
      docResultRef.value +=
          '${rowHtml + propColHtml + ts.str(ts.stepHost.resourceString('SEQ_FILE_DOC', 'DOC_STEP_COMMENT'), '%-30s') + valColHtml + tmpString}\n'; // Comment
    }
    if (ts.cond('PropertyExists("Parameters.Step.InBuf") ? Parameters.Step.InBuf != "" : False')) {
      // precondition of Process InBuf
      tmpString = step.InBuf as String; // Process InBuf
      ts.eval('\nFindAndReplace(Locals.tmpString, "<", "&lt;")'); // Process InBuf (cont.)
      ts.eval('\nFindAndReplace(Locals.tmpString, ">", "&gt;")'); // Process InBuf (cont.)
      ts.eval('\nFindAndReplace(Locals.tmpString, "\\n", "<BR>")'); // Process InBuf (cont.)
    }
    if (ts.cond('PropertyExists("Parameters.Step.InBuf") ? Parameters.Step.InBuf != "" : False')) {
      // precondition of InBuf
      docResultRef.value +=
          '${rowHtml + propColHtml + ts.str(ts.stepHost.resourceString('SEQ_FILE_DOC', 'DOC_STEP_INBUF'), '%-30s') + valColHtml + tmpString}\n'; // InBuf
    }
    // status expression: (Step.Result.Status == "Done" && (Step.TS.SData.ThreadOpt == 0 || Step.TS.SData.ThreadOpt == 3)) ? "Passed" : Step.Result.Status
    final docResultRef2 = ts.Ref<String>(docResultRef.value);
    addRequirementsResult.Status = await writeRequirementsElements(
      requirements: step.TS.Requirements,
      docResult: docResultRef2,
    ); // Add Requirements
    docResultRef.value = docResultRef2.value;
    addRequirementsResult.Status = addRequirementsResult.Status == 'Done'
        ? 'Passed'
        : addRequirementsResult.Status; // status expression
    run.record(addRequirementsResult.Status);
    docResultRef.value +=
        '${rowHtml + propColHtml + ts.str(ts.stepHost.resourceString('SEQ_FILE_DOC', 'DOC_LOAD_AND_UNLOAD_OPTION'), '%-30s') + valColHtml + ts.stepHost.resourceString('LOAD OPTION STRINGS', step.TS.LoadOpt)}, ${ts.stepHost.resourceString('UNLOAD OPTION STRINGS', step.TS.UnloadOpt)}\n'; // Load and Unload Option
    if (step.TS.ResultOption != 1) {
      // precondition of Record Results
      docResultRef.value +=
          '${rowHtml + propColHtml + ts.str(ts.stepHost.resourceString('SEQ_FILE_DOC', 'DOC_STEP_RECORD_RESULTS'), '%-30s') + valColHtml + (step.TS.ResultOption == 0 ? ts.stepHost.resourceString('STEP_PROP_DLG', 'RESULT_RECORDING_OPTION_DISABLED') : (step.TS.ResultOption == 1 ? ts.stepHost.resourceString('STEP_PROP_DLG', 'RESULT_RECORDING_OPTION_ENABLED') : ts.stepHost.resourceString('STEP_PROP_DLG', 'RESULT_RECORDING_OPTION_ENABLED_OVERRIDE_SEQUENCE_SETTING')))}\n'; // Record Results
    }
    if (!ts.truthy(step.TS.StepFCSeqF)) {
      // precondition of Step Fail Causes Seq Fail
      docResultRef.value +=
          '${rowHtml + propColHtml + ts.str(ts.stepHost.resourceString('SEQ_FILE_DOC', 'DOC_STEP_STEP_FAIL_SEQ_FAIL'), '%-40s') + valColHtml + ts.str(step.TS.StepFCSeqF)}\n'; // Step Fail Causes Seq Fail
    }
    if (ts.truthy(step.TS.IgnoreRTE)) {
      // precondition of Ignore Run-Time Error
      docResultRef.value +=
          '${rowHtml + propColHtml + ts.str(ts.stepHost.resourceString('SEQ_FILE_DOC', 'DOC_STEP_IGNORE_RTE'), '%-30s') + valColHtml + ts.str(step.TS.IgnoreRTE)}\n'; // Ignore Run-Time Error
    }
    // goto -> --- Begin of Multiple Limits ---
    if (ts.cond('PropertyExists("Parameters.Step.Result.Measurement")')) {
      // precondition of Skip to Multiple Limits Section
      // Skip to Multiple Limits Section [Goto]: no code module
      break skipToBeginOfMultipleLimits; // post action
    }
    if (ts.cond('PropertyExists("Parameters.Step.Limits.String") ')) {
      // precondition of Process String Limit
      tmpString = step.Limits.String as String; // Process String Limit
      ts.eval('\nFindAndReplace(Locals.tmpString, "<", "&lt;")'); // Process String Limit (cont.)
      ts.eval('\nFindAndReplace(Locals.tmpString, ">", "&gt;")'); // Process String Limit (cont.)
      ts.eval('\nFindAndReplace(Locals.tmpString, "\\n", "<BR>")'); // Process String Limit (cont.)
    }
    if (ts.cond('PropertyExists("Parameters.Step.Limits.String") ')) {
      // precondition of String Limit
      docResultRef.value +=
          '${rowHtml + propColHtml + ts.str(ts.stepHost.resourceString('SEQ_FILE_DOC', 'DOC_STEP_LIMIT_STRING'), '%-30s') + valColHtml + tmpString}\n'; // String Limit
    }
    if (ts.cond('PropertyExists("Parameters.Step.DataSource")')) {
      // precondition of Data Source
      ts.eval(
        'Parameters.DocResult += Locals.RowHTML+ Locals.PropColHTML +\n	Str(GetResourceString("SEQ_FILE_DOC", "DOC_STEP_DATASOURCE"), "%-30s") +\n	Locals.ValColHTML +\n	LocalizeExpression(Parameters.Step.DataSource) + "\\n"\n',
      ); // Data Source
    }
  }
  // label: --- Begin of Multiple Limits ---
  // status expression: (Step.Result.Status == "Done" && (Step.TS.SData.ThreadOpt == 0 || Step.TS.SData.ThreadOpt == 3)) ? "Passed" : Step.Result.Status
  if (ts.cond(
    'AllOf(Locals.StepTypeName == "NI_MultipleNumericLimitTest", PropertyExists("Parameters.Step.Result.Measurement"))',
  )) {
    // precondition of Add Multiple Numeric Limits
    addMultipleNumericLimitsResult.Status = await writeMultipleNumericLimitLimits(); // Add Multiple Numeric Limits
    addMultipleNumericLimitsResult.Status = addMultipleNumericLimitsResult.Status == 'Done'
        ? 'Passed'
        : addMultipleNumericLimitsResult.Status; // status expression
    run.record(addMultipleNumericLimitsResult.Status);
  } else {
    addMultipleNumericLimitsResult.Status = 'Skipped';
  }
  //   Return Value -> Locals.ExecFlow
  //   options <- 0x1 ' StepDescOption_Long
  ts.notExported('cModule call: Get Execution Flow'); // Get Execution Flow [Action]
  if (ts.truthy(execFlow != '')) {
    // precondition of Execution Flow
    docResultRef.value +=
        '${rowHtml + propColHtml + ts.str(ts.stepHost.resourceString('SEQ_FILE_DOC', 'DOC_STEP_EXEC_FLOW'), '%-30s') + valColHtml}<XMP>$execFlow</XMP>\n'; // Execution Flow
  }
  docResultRef.value += '</TABLE></BLOCKQUOTE>\n'; // Step Footer

  return run.status;
}

/// Sequence `Write Subproperties`.
Future<String> writeSubproperties({
  dynamic root,
  String docResult = '',
  String parentPropLookupStr = '',
  bool isRecursiveCall = false,
  dynamic docOptions,
}) async {
  const int numSubproperties = 0; // Num — default: 0
  int i = 0; // Num — default: 0
  const String subpropName = ''; // Str
  bool isHidden = false; // Bool — default: false
  const int subpropFlags = 0; // Num — default: 0

  final run = ts.SequenceRun();
  final dynamic displayPropertyResult = ts.PropObj({
    'Error': ts.PropObj({'Code': 0, 'Msg': '', 'Occurred': false}),
    'Status': '',
    'ReportText': '',
    'Common': ts.PropObj(),
  }); // result of DisplayProperty
  final dynamic displaySubpropertiesOfSubpropertyResult = ts.PropObj({
    'Error': ts.PropObj({'Code': 0, 'Msg': '', 'Occurred': false}),
    'Status': '',
    'ReportText': '',
    'Common': ts.PropObj(),
  }); // result of DisplaySubpropertiesOfSubproperty

  endMain:
  {
    //   Return Value -> Locals.NumSubproperties
    //   lookupString <- Parameters.ParentPropLookupStr
    ts.notExported('cModule call: GetNumSubProperties'); // GetNumSubProperties [Action]
    backToGotoEndWhenDone:
    while (true) {
      // goto -> <End>
      if (i == numSubproperties) {
        // precondition of Goto End When Done
        // Goto End When Done [Goto]: no code module
        break endMain; // post action
      }
      //   Return Value -> Locals.SubpropName
      //   lookupString <- Parameters.ParentPropLookupStr
      //   index <- Locals.i
      //   options <- 0
      ts.notExported('cModule call: GetSubPropName'); // GetSubPropName [Action]
      parentPropLookupStr != '' ? '$parentPropLookupStr.$subpropName' : subpropName; // BuildNewLookupStr
      //   Return Value -> Locals.SubpropFlags
      //   lookupString <- Locals.SubpropLookupStr
      //   options <- 0
      ts.notExported('cModule call: GetFlags'); // GetFlags [Action]
      subpropFlags & 8 != 0 ? (isHidden = true) : (isHidden = false); // IsHidden
      // status expression: (Step.Result.Status == "Done" && (Step.TS.SData.ThreadOpt == 0 || Step.TS.SData.ThreadOpt == 3)) ? "Passed" : Step.Result.Status
      if (isHidden == false || ts.truthy(docOptions.ShowHidden)) {
        // precondition of DisplayProperty
        displayPropertyResult.Status = await writePropertyDetails(); // DisplayProperty
        displayPropertyResult.Status = displayPropertyResult.Status == 'Done'
            ? 'Passed'
            : displayPropertyResult.Status; // status expression
        run.record(displayPropertyResult.Status);
      } else {
        displayPropertyResult.Status = 'Skipped';
      }
      // status expression: (Step.Result.Status == "Done" && (Step.TS.SData.ThreadOpt == 0 || Step.TS.SData.ThreadOpt == 3)) ? "Passed" : Step.Result.Status
      if ((isHidden == false || ts.truthy(docOptions.ShowHidden)) && ts.truthy(docOptions.ShowSubproperties)) {
        // precondition of DisplaySubpropertiesOfSubproperty
        displaySubpropertiesOfSubpropertyResult.Status =
            await writeSubproperties(); // DisplaySubpropertiesOfSubproperty
        displaySubpropertiesOfSubpropertyResult.Status = displaySubpropertiesOfSubpropertyResult.Status == 'Done'
            ? 'Passed'
            : displaySubpropertiesOfSubpropertyResult.Status; // status expression
        run.record(displaySubpropertiesOfSubpropertyResult.Status);
      } else {
        displaySubpropertiesOfSubpropertyResult.Status = 'Skipped';
      }
      i += 1; // Increment index
      if (isRecursiveCall == false) {
        // precondition of Update Percent Done
        ts.notExported('cModule call: Update Percent Done'); // Update Percent Done [Action]
      }
      // goto -> Goto End When Done
      // Loop back around [Goto]: no code module
      continue backToGotoEndWhenDone; // post action
    }
  }

  return run.status;
}

/// Sequence `Write Array Elements`.
Future<String> writeArrayElements({
  dynamic root,
  ts.Ref<String>? docResult,
  String arrayPropLookupStr = '',
  dynamic docOptions,
}) async {
  final docResultRef = docResult ?? ts.Ref<String>('');
  int currentOffset = 0; // Num — default: 0
  const int numElements = 0; // Num — default: 0
  const String rowHtml = '<TR>'; // Str
  const String colHtml = '<TD WIDTH=33% colspan=3 NOWRAP=NOWRAP BGCOLOR=LIGHTBLUE>'; // Str

  final run = ts.SequenceRun();
  final dynamic displayPropertyResult = ts.PropObj({
    'Error': ts.PropObj({'Code': 0, 'Msg': '', 'Occurred': false}),
    'Status': '',
    'ReportText': '',
    'Common': ts.PropObj(),
  }); // result of DisplayProperty
  final dynamic displaySubpropertiesResult = ts.PropObj({
    'Error': ts.PropObj({'Code': 0, 'Msg': '', 'Occurred': false}),
    'Status': '',
    'ReportText': '',
    'Common': ts.PropObj(),
  }); // result of DisplaySubproperties

  endMain:
  {
    skipToMaxNumArrayElementsMsg:
    {
      //   lookupString <- Parameters.ArrayPropLookupStr
      //   options <- 0
      //   lowerBounds [out]
      //   upperBounds [out]
      //   numElements -> Locals.NumElements
      //   elementType [out]
      ts.notExported('cModule call: GetNumElements'); // GetNumElements [Action]
      backToStartOfLoop:
      while (true) {
        // label: --- Start of Loop ---
        // goto -> --- Max Num Array Elements Msg ---
        if (currentOffset == docOptions.MaxNumArrayElementsToShow && currentOffset != numElements) {
          // precondition of Check for Max Num Array Elements
          // Check for Max Num Array Elements [Goto]: no code module
          break skipToMaxNumArrayElementsMsg; // post action
        }
        // goto -> <End>
        if (currentOffset == numElements) {
          // precondition of Goto End When Done
          // Goto End When Done [Goto]: no code module
          break endMain; // post action
        }
        //   Return Value -> Locals.CurrentArrayIndex
        //   lookupString <- Parameters.ArrayPropLookupStr
        //   options <- 0
        //   offset <- Locals.CurrentOffset
        ts.notExported('cModule call: GetArrayIndexFromOffset'); // GetArrayIndexFromOffset [Action]
        // status expression: (Step.Result.Status == "Done" && (Step.TS.SData.ThreadOpt == 0 || Step.TS.SData.ThreadOpt == 3)) ? "Passed" : Step.Result.Status
        displayPropertyResult.Status = await writePropertyDetails(); // DisplayProperty
        displayPropertyResult.Status = displayPropertyResult.Status == 'Done'
            ? 'Passed'
            : displayPropertyResult.Status; // status expression
        run.record(displayPropertyResult.Status);
        // status expression: (Step.Result.Status == "Done" && (Step.TS.SData.ThreadOpt == 0 || Step.TS.SData.ThreadOpt == 3)) ? "Passed" : Step.Result.Status
        displaySubpropertiesResult.Status = await writeSubproperties(); // DisplaySubproperties
        displaySubpropertiesResult.Status = displaySubpropertiesResult.Status == 'Done'
            ? 'Passed'
            : displaySubpropertiesResult.Status; // status expression
        run.record(displaySubpropertiesResult.Status);
        currentOffset += 1; // Inc Loop Var
        // goto -> --- Start of Loop ---
        // Loop back around [Goto]: no code module
        continue backToStartOfLoop; // post action
      }
    }
    // label: --- Max Num Array Elements Msg ---
    docResultRef.value +=
        '${rowHtml + colHtml + arrayPropLookupStr}[...] --- ${ts.stepHost.resourceString('SEQ_FILE_DOC', 'DOC_MAX_ARRAY_DISPLAY_EXCEEDED')}'; // Add Max Exceeded Msg
  }

  return run.status;
}

/// Sequence `Write Property Details`.
Future<String> writePropertyDetails({
  ts.Ref<String>? docResult,
  dynamic root,
  String propertyToDisplayName = '',
  dynamic docOptions,
}) async {
  final docResultRef = docResult ?? ts.Ref<String>('');
  const int valueType = 0; // Num — default: 0
  const bool isArray = false; // Bool — default: false
  String typeName = ''; // Str
  String subpropValue = '...'; // Str
  const int subpropFlags = 0; // Num — default: 0
  String byRefStr = ''; // Str
  const String rowHtml = '<TR>'; // Str
  const String propColHtml = '<TD WIDTH=33% NOWRAP=NOWRAP BGCOLOR=LIGHTBLUE>'; // Str
  const String typeColHtml = '<TD WIDTH=33% BGCOLOR=GOLDENROD>'; // Str
  const String valColHtml = '<TD WIDTH=33% BGCOLOR=LIGHTGREEN>'; // Str

  final run = ts.SequenceRun();
  final dynamic tryToEvaluateResult = ts.PropObj({
    'Error': ts.PropObj({'Code': 0, 'Msg': '', 'Occurred': false}),
    'Status': '',
    'ReportText': '',
    'Common': ts.PropObj(),
  }); // result of TryToEvaluate
  final dynamic displayArrayElementsResult = ts.PropObj({
    'Error': ts.PropObj({'Code': 0, 'Msg': '', 'Occurred': false}),
    'Status': '',
    'ReportText': '',
    'Common': ts.PropObj(),
  }); // result of DisplayArrayElements

  skipToSkipEvaluate:
  {
    //   Return Value -> Locals.valueType
    //   lookupString <- Parameters.PropertyToDisplayName
    //   options <- 0
    //   isObject -> Locals.isObject
    //   isArray -> Locals.isArray
    //   typeName -> Locals.typeName
    ts.notExported('cModule call: GetTypeInfo'); // GetTypeInfo [Action]
    // Normally Evaluate() should only fail if the property name has invalid characters in it.
    // label: --- Test Evaluate Error ---
    // ignores run-time errors
    // failure does NOT fail the sequence
    ts.eval('Evaluate("Parameters.Root." + Parameters.PropertyToDisplayName)'); // TryToEvaluate
    tryToEvaluateResult.Status = 'Done';
    if (tryToEvaluateResult.Status == 'Error') {
      // precondition of Document Error
      subpropValue = tryToEvaluateResult.Error.Msg as String; // Document Error
    }
    // goto -> --- Skip Evaluate ---
    if (tryToEvaluateResult.Status == 'Error') {
      // precondition of Skip Evaluate
      // Skip Evaluate [Goto]: no code module
      break skipToSkipEvaluate; // post action
    }
    typeName = root.GetPropertyObject(propertyToDisplayName, 0).Type.DisplayString as String; // GetTypeNameForDisplay
    // Get the value of a number, boolean or activex property
    if (ts.truthy(valueType == 2 || valueType == 3 || valueType == 5)) {
      // precondition of GetSubPropValue1
      ts.eval(
        'Locals.SubpropValue = Str(Evaluate("Parameters.Root." + Parameters.PropertyToDisplayName))',
      ); // GetSubPropValue1
    }
    // Get the value of a string property
    if (ts.truthy(valueType == 1)) {
      // precondition of GetSubPropValue2
      ts.eval(
        'Locals.SubpropValue = "\\"" + Evaluate("Parameters.Root." + Parameters.PropertyToDisplayName) + "\\""',
      ); // GetSubPropValue2
    }
    // Get the value of an enum property
    if (ts.cond('Locals.valueType == PropValType_Enum')) {
      // precondition of GetSubPropValue7
      ts.eval(
        ' Evaluate("Parameters.Root." + Parameters.PropertyToDisplayName).GetDisplayNames("", PropOption_NoOptions, Locals.Unused, Locals.SubpropValue)',
      ); // GetSubPropValue7
    }
  }
  // label: --- Skip Evaluate ---
  ts.eval('FindAndReplace(Locals.SubpropValue, "<", "&lt;")'); // Process SubpropValue
  ts.eval('\nFindAndReplace(Locals.SubpropValue, ">", "&gt;")'); // Process SubpropValue (cont.)
  ts.eval('\nFindAndReplace(Locals.SubpropValue, "\\n", "<BR>")'); // Process SubpropValue (cont.)
  //   Return Value -> Locals.SubpropFlags
  //   lookupString <- Parameters.PropertyToDisplayName
  //   options <- 0
  ts.notExported('cModule call: GetFlags'); // GetFlags [Action]
  subpropFlags & 4 != 0
      ? (byRefStr = ' (${ts.stepHost.resourceString('SEQUENCING ADAPTER', 'PASS_BYREFERENCE')})')
      : (byRefStr = ''); // IsByRef
  docResultRef.value +=
      '${rowHtml + propColHtml + propertyToDisplayName + typeColHtml + typeName + byRefStr + valColHtml + subpropValue}\n'; // Add Display String
  // status expression: (Step.Result.Status == "Done" && (Step.TS.SData.ThreadOpt == 0 || Step.TS.SData.ThreadOpt == 3)) ? "Passed" : Step.Result.Status
  if (ts.truthy(isArray) && ts.truthy(docOptions.ShowArrayElements)) {
    // precondition of DisplayArrayElements
    displayArrayElementsResult.Status = await writeArrayElements(); // DisplayArrayElements
    displayArrayElementsResult.Status = displayArrayElementsResult.Status == 'Done'
        ? 'Passed'
        : displayArrayElementsResult.Status; // status expression
    run.record(displayArrayElementsResult.Status);
  } else {
    displayArrayElementsResult.Status = 'Skipped';
  }

  return run.status;
}

/// Sequence `Write Multiple Numeric Limit Limits`.
Future<String> writeMultipleNumericLimitLimits({dynamic step, ts.Ref<String>? docResult}) async {
  final docResultRef = docResult ?? ts.Ref<String>('');
  int currentOffset = 0; // Num — default: 0
  const int numElements = 0; // Num — default: 0
  const String rowHtml = '<TR>'; // Str
  const String propColHtml = '<TD WIDTH=30% NOWRAP=NOWRAP BGCOLOR=LIGHTBLUE>'; // Str
  const String valColHtml = '<TD WIDTH=70% BGCOLOR=LIGHTGREEN>'; // Str
  bool oneLimitOnly = false; // Bool — default: false
  const String lowLimitFmt = ''; // Str
  const String highLimitFmt = ''; // Str

  final run = ts.SequenceRun();

  skipToAfterLoop:
  {
    //   lookupString <- ""
    //   options <- 0
    //   lowerBounds [out]
    //   upperBounds [out]
    //   numElements -> Locals.NumElements
    //   elementType [out]
    ts.notExported('cModule call: GetNumElements'); // GetNumElements [Action]
    backToStartOfLoop:
    while (true) {
      // label: --- Start of Loop ---
      // goto -> --- After Loop ---
      if (currentOffset == numElements) {
        // precondition of Goto After Loop Section When Done
        // Goto After Loop Section When Done [Goto]: no code module
        break skipToAfterLoop; // post action
      }
      oneLimitOnly = false; // Initialize Local Variables
      ts.eval(
        '\nParameters.DocResult += Locals.RowHTML+\n"<TD COLSPAN=2 ALIGN=LEFT WIDTH=100% BGCOLOR=TEAL>" + "<FONT COLOR=WHITE>" + ResStr("SEQ_FILE_DOC", "MEAS_NAME_LBL") + " " + NameOf(Parameters.Step.Result.Measurement[Locals.CurrentOffset])  + "</FONT>\\n"\n',
      ); // Header
      if (ts.cond('PropertyExists("Parameters.Step.Result.Measurement[" + Str(Locals.CurrentOffset) + "].Comp")')) {
        // precondition of Comparison Type
        docResultRef.value +=
            '${rowHtml + propColHtml + ts.str(ts.stepHost.resourceString('SEQ_FILE_DOC', 'DOC_STEP_COMP_TYPE'), '%-30s') + valColHtml + (step.Result.Measurement[currentOffset].Comp as String)}\n'; // Comparison Type
      }
      if (ts.cond(
        '#NoValidation(\nAllOf(PropertyExists("Parameters.Step.Result.Measurement[" + Str(Locals.CurrentOffset) + "].Comp"), PropertyExists("Parameters.Step.Result.Measurement[" + Str(Locals.CurrentOffset) + "].Limits.High"), AnyOf(Parameters.Step.Result.Measurement[ Locals.CurrentOffset ].Comp == "EQ", Parameters.Step.Result.Measurement[ Locals.CurrentOffset ].Comp == "NE", Parameters.Step.Result.Measurement[ Locals.CurrentOffset ].Comp == "GT", Parameters.Step.Result.Measurement[ Locals.CurrentOffset ].Comp == "LT", Parameters.Step.Result.Measurement[ Locals.CurrentOffset ].Comp == "GE", Parameters.Step.Result.Measurement[ Locals.CurrentOffset ].Comp == "LE"))\n)',
      )) {
        // precondition of One Limit Only?
        oneLimitOnly = true; // One Limit Only?
      }
      if (ts.cond(
        'PropertyExists("Parameters.Step.Result.Measurement[" + Str(Locals.CurrentOffset) + "].Limits.Low")',
      )) {
        // precondition of Get Low Limit Format
        //   Return Value -> Locals.LowLimitFmt
        ts.notExported('cModule call: Get Low Limit Format'); // Get Low Limit Format [Action]
      }
      if (ts.cond(
        'PropertyExists("Parameters.Step.Result.Measurement[" + Str(Locals.CurrentOffset) + "].Limits.High")',
      )) {
        // precondition of Get High Limit Format
        //   Return Value -> Locals.HighLimitFmt
        ts.notExported('cModule call: Get High Limit Format'); // Get High Limit Format [Action]
      }
      if (ts.cond(
        '#NoValidation(AllOf(PropertyExists("Parameters.Step.Result.Measurement[" + Str(Locals.CurrentOffset) + "].Limits.Low"), Parameters.Step.Result.Measurement[Locals.CurrentOffset].Comp != "LOG"))',
      )) {
        // precondition of Low Limit
        docResultRef.value +=
            '${rowHtml + propColHtml + (oneLimitOnly ? ts.stepHost.resourceString('SEQ_FILE_DOC', 'DOC_STEP_LIMIT') : ts.stepHost.resourceString('SEQ_FILE_DOC', 'DOC_STEP_LIMIT_LOW')) + valColHtml + ts.str(step.Result.Measurement[currentOffset].Limits.Low, lowLimitFmt)}\n'; // Low Limit
      }
      if (ts.cond(
        '#NoValidation(AllOf(PropertyExists("Parameters.Step.Result.Measurement[" + Str(Locals.CurrentOffset) + "].Limits.High"), Parameters.Step.Result.Measurement[Locals.CurrentOffset].Comp != "LOG", !Locals.OneLimitOnly))',
      )) {
        // precondition of High Limit
        docResultRef.value +=
            '${rowHtml + propColHtml + ts.str(ts.stepHost.resourceString('SEQ_FILE_DOC', 'DOC_STEP_LIMIT_HIGH'), '%-30s') + valColHtml + ts.str(step.Result.Measurement[currentOffset].Limits.High, highLimitFmt)}\n'; // High Limit
      }
      if (ts.cond(
        '#NoValidation(AllOf(PropertyExists("Parameters.Step.Result.Measurement[" + Str(Locals.CurrentOffset) + "].Units"), Parameters.Step.Result.Measurement[Locals.CurrentOffset].Units != ""))',
      )) {
        // precondition of Units
        docResultRef.value +=
            '${rowHtml + propColHtml + ts.str(ts.stepHost.resourceString('SEQ_FILE_DOC', 'DOC_STEP_UNITS'), '%-30s') + valColHtml + (step.Result.Measurement[currentOffset].Units as String)}\n'; // Units
      }
      if (ts.cond(
        'AllOf(PropertyExists("Parameters.Step.DataSourceArray[" + Str(Locals.CurrentOffset) + "]"), Parameters.Step.UseIndividualDataSources)',
      )) {
        // precondition of Individual Data Source
        ts.eval(
          '\nParameters.DocResult += Locals.RowHTML+ Locals.PropColHTML +\n	Str(GetResourceString("SEQ_FILE_DOC", "DOC_STEP_DATASOURCE"), "%-30s") +\n	Locals.ValColHTML +\n	LocalizeExpression(Parameters.Step.DataSourceArray[Locals.CurrentOffset]) + "\\n"\n',
        ); // Individual Data Source
      }
      currentOffset += 1; // Inc Loop Var
      // goto -> --- Start of Loop ---
      // Loop back around [Goto]: no code module
      continue backToStartOfLoop; // post action
    }
  }
  // label: --- After Loop ---
  if (ts.truthy(numElements > 0)) {
    // precondition of Footer
    docResultRef.value +=
        '$rowHtml<TD COLSPAN=2 ALIGN=LEFT WIDTH=100% BGCOLOR=TEAL><FONT COLOR=WHITE>${ts.stepHost.resourceString('SEQ_FILE_DOC', 'END_OF_MEAS_LBL')}</FONT>\n'; // Footer
  }
  if (ts.cond(
    '#NoValidation(AllOf(PropertyExists("Parameters.Step.DataSource"), !Parameters.Step.UseIndividualDataSources, Locals.NumElements > 0))',
  )) {
    // precondition of Data Source
    ts.eval(
      'Parameters.DocResult += Locals.RowHTML+ Locals.PropColHTML +\n	Str(GetResourceString("SEQ_FILE_DOC", "DOC_STEP_DATASOURCE"), "%-30s") +\n	Locals.ValColHTML +\n	LocalizeExpression(Parameters.Step.DataSource) + "\\n"\n',
    ); // Data Source
  }

  return run.status;
}

/// Sequence `Write Requirements Elements`.
Future<String> writeRequirementsElements({dynamic requirements, ts.Ref<String>? docResult}) async {
  final docResultRef = docResult ?? ts.Ref<String>('');
  String currentReqElement = ''; // Str
  String tmpString = ''; // Str
  const String rowHtml = '<TR>'; // Str
  const String propColHtml = '<TD WIDTH=30% NOWRAP=NOWRAP BGCOLOR=LIGHTBLUE>'; // Str
  const String valColHtml = '<TD WIDTH=70% BGCOLOR=LIGHTGREEN>'; // Str

  final run = ts.SequenceRun();

  // label: Process Requirements
  for (final element in ts.iterate(requirements.Links)) {
    currentReqElement = element as String;
    tmpString += '$currentReqElement\n'; // Get Requirments
  }
  if (ts.len(tmpString) > 0) {
    // precondition of Requirements
    ts.eval('FindAndReplace(Locals.tmpString, "<", "&lt;")'); // Requirements
    ts.eval('\nFindAndReplace(Locals.tmpString, ">", "&gt;")'); // Requirements (cont.)
    ts.eval('\nFindAndReplace(Locals.tmpString, "\\n", "<br>")'); // Requirements (cont.)
    docResultRef.value +=
        '${rowHtml + propColHtml + ts.str(ts.stepHost.resourceString('SEQ_FILE_DOC', 'DOC_STEP_REQUIREMENTS'), '%-30s') + valColHtml + tmpString}\n'; // Requirements (cont.)
  }

  return run.status;
}
